package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.outbox;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.fasterxml.jackson.databind.ObjectMapper;
class ModerationOutboxTests{@Test void producesVersionedEnvelope()throws Exception{ModerationOutboxRepository repo=mock(ModerationOutboxRepository.class);ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();new JpaModerationOutboxAdapter(repo,mapper).append("moderation.report.created","moderation-report","r1","u1","c1",Map.of("reportId","r1"));ArgumentCaptor<ModerationOutboxEvent>c=ArgumentCaptor.forClass(ModerationOutboxEvent.class);verify(repo).save(c.capture());var json=mapper.readTree(c.getValue().getPayload());assertEquals(1,json.get("eventVersion").asInt());assertEquals("moderation-trust-service",json.get("producer").asText());assertEquals("c1",json.get("correlationId").asText());}}
